SELECT DISTINCT contestant_number
FROM VOTES
ORDER BY contestant_number;

SELECT COUNT(vote_id) AS vote_id_count
FROM VOTES
WHERE contestant_number = 5;

SELECT property_name
FROM Properties
WHERE room_count > 1;

SELECT AVG(CAST(d.age AS REAL)) AS average_age
FROM Dogs AS d
WHERE EXISTS (SELECT 1 FROM Treatments AS t WHERE t.dog_id = d.dog_id);

SELECT Location
FROM shop
ORDER BY Number_products DESC
LIMIT 1;
